const EVENTS = [
  'onclick', 'onmouseover', 'onmouseenter', 'onfocus', 'onblur', 'onerror', 'onload', 'onanimationstart',
  'onbeforeinput', 'oncopy', 'onpointerdown', 'ontransitionend', 'onwheel', 'ontouchstart', 'onkeydown', 'onauxclick',
];
const KEPT_TAGS = ['b', 'i', 'u', 's', 'a href="https://ok.example"', 'span style="color:red"', 'p', 'font color="#ff0000"'];

const GENERATED = KEPT_TAGS.flatMap((tag) => {
  const name = tag.split(' ')[0];
  return EVENTS.map((event, i) => `<${tag} ${event}="alert(${i})">${name}</${name}>`);
});

/** Nesting thousands of levels deep: the reader must stay flat and must not recurse per level. */
export const DEEP_NESTING: readonly string[] = [
  `${'<ul><li>'.repeat(10_000)}deep item<img src=x onerror=alert(1)>`,
  `${'<ol>'.repeat(10_000)}deep bare list`,
  `${'<blockquote>'.repeat(15_000)}deep nested quote`,
  `${'<ul><li><blockquote><div onclick=alert(1)>'.repeat(5_000)}deep mixed`,
  `${'<b><i><span style="color:#ff0000">'.repeat(10_000)}deep marks`,
];

export const XSS_PAYLOADS: readonly string[] = [...HAND_WRITTEN, ...GENERATED, ...DEEP_NESTING];
